package com.androdr.ioc

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Test
import java.io.File

/**
 * The bundled cold-start tracker registry (`res/raw/trackers.yml`) must equal the
 * pinned submodule's `ioc-data/trackers.yml`. The file is generated by
 * `scripts/merge-ioc-data.py` (`COPIED_FILES`), never hand-edited.
 */
class TrackerRegistryBundleCrossCheckTest {

    private fun firstExisting(vararg paths: String): File? =
        paths.map { File(it) }.firstOrNull { it.isFile }

    @Test
    fun `bundled trackers_yml equals the pinned submodule file`() {
        val bundled = firstExisting("src/main/res/raw/trackers.yml", "app/src/main/res/raw/trackers.yml")
        val repo = firstExisting(
            "../third-party/android-sigma-rules/ioc-data/trackers.yml",
            "third-party/android-sigma-rules/ioc-data/trackers.yml",
        )
        assertNotNull("bundled trackers.yml missing", bundled)
        assertNotNull("submodule ioc-data/trackers.yml missing", repo)
        assertEquals(repo!!.readText(), bundled!!.readText())
    }
}
